        return [0]
    elif n == 2:
        return [0, 1]
    else:
        a = generate_circuit(n // 2)
        b = generate_circuit(n - n // 2)
        return [0] + a + [1] + b

def compute_function_field(circuit):
    if len(circuit) == 1:
        return {0: 1}
    else:
        field = {}
        for i in range(len(circuit)):
            if circuit[i] == 0:
                for key, value in compute_function_field(circuit[:i]).items():
                    field[key * 2] = value
            else:
                for key, value in compute_function_field(circuit[:i]).items():
                    field[key * 2 + 1] = value
        return field

def compute_brauer_group_order(field):
    order = 1
    for key in field:
        if key != 0:
            order *= abs(key)
    return order

